        assert.ok(down.indexOf('\u26A0') !== -1, '⚠ marker present');
        assert.equal(down.indexOf('BLOCKING'), -1, 'BLOCKING word demoted');
        assert.ok(down.indexOf('IMPORTANT') !== -1, 'IMPORTANT word present');
