var BLOCKING_MARKER_RE = /(\uD83D\uDEA8)|((?:^|[^\w-])BLOCKING\b)/i;

// Leading "🚨 BLOCKING"-style marker of a finding body (bold-tolerant).
var LEADING_MARKER_RES = [
