    return false;
}

/**
 * A verifiable citation: a `file:line` / `#L`-anchor reference anywhere in
 * the text, or a doc URL on a trusted host. opts.trustedDocHosts (array or
 * { trustedDocHosts: [...] }) overrides the default host list.
