function hostIsTrusted(host, hosts) {
    var h = String(host || '').toLowerCase();
    if (!h) return false;
    for (var i = 0; i < hosts.length; i++) {
        var t = String(hosts[i]).toLowerCase();
        if (h === t || h.substring(h.length - t.length - 1) === '.' + t) return true;
    }
