 */
function readMarkdownFile(filePath, ticketKey, workingDir) {
    if (!filePath) {
        return '';
    }
    try {
        const content = outputFiles.readOutputFile(filePath, {
            ticketKey: ticketKey,
            workingDir: workingDir
        });
        if (content && content.trim() !== '') {
            return content;
        }
    } catch (error) {
